FACT_NPS_M = 'let\n   // Source = Sql.Database("sql-datamesh-datalake-prod-001-ondemand.sql.azuresynapse.net", "datalake"),\n   // udm_datamart_cust_exp_cust_exp_fact_data_v1 = Source{[Schema="udm_datamart_cust_exp",Item="cust_exp_fact_data_v2"]}[Data],\n     Source = Value.NativeQuery(Databricks.Catalogs("adb-6954534548722724.4.azuredatabricks.net", "/sql/1.0/warehouses/ba6033a2676da150", [Catalog="udm_datamart_cust_exp", Database=null, QueryTags=null, EnableAutomaticProxyDiscovery=null, Implementation="2.0", MetricViewBiCompatibilityMode=null]){[Name="udm_datamart_cust_exp",Kind="Database"]}[Data], "SELECT *,#(lf)    TO_DATE(concat( LEFT(fiscper, 4),\'-\', RIGHT(fiscper, 2), \'-15\')) fiscper_date#(lf)    FROM (#(lf)SELECT #(lf)    cg_id,#(lf)    country_id,#(lf)    fiscper,#(lf)    primary_drivers,#(lf)    secondary_drivers,#(lf)    nps,#(lf)    Classification_ID,#(lf)    customer_channel,#(lf)    customer_rating,#(lf)    COUNT(secondary_drivers) over(partition by cg_id, country_id, fiscper) SecondaryDriversCount,#(lf)    customer_rating / COUNT(secondary_drivers) over(partition by cg_id, country_id, fiscper) NPS_Contribution_per_Driver#(lf)FROM(#(lf)  SELECT * EXCEPT (process_run_id, date_email_sent, date_sent),#(lf)  CASE WHEN nps >= 9 THEN 1#(lf)         WHEN nps >= 7 AND nps < 9 THEN 0#(lf)         ELSE -1#(lf)    END AS Customer_Rating,#(lf)    CASE WHEN nps >= 9 THEN 1#(lf)         WHEN nps >= 7 AND nps < 9 THEN 3#(lf)         ELSE 2#(lf)    END AS Classification_ID#(lf)from#(lf)  `dc_datalake_prod_001`.`udm_datamart_cust_exp`.`cust_exp_drivers_nps_contribution`#(lf)WHERE#(lf)  lower(touchpoint) like \'relationship\' and #(lf)  secondary_drivers in (#(lf)    \'Accurately invoiced product order delivery\',#(lf)    \'Availability of products\',#(lf)    \'On-time delivery\',#(lf)    \'Reliability of promises\',#(lf)    \'Responsiveness of sales teams\'#(lf)  )#(lf))#(lf)#(lf)GROUP BY#(lf)    cg_id,#(lf)    country_id,#(lf)    fiscper,#(lf)    primary_drivers,#(lf)    secondary_drivers,#(lf)    nps,#(lf)    Classification_ID,#(lf)    customer_rating,#(lf)    customer_channel#(lf)    )", null, [EnableFolding=true]),\n    \n    #"Kept First Rows" = Table.FirstN(Source,RowLimit),\n \xa0\xa0 Result = if RowLimit > 0 then #"Kept First Rows" else Source\nin\n    Result'

FACT_OTC_M = 'let\n    //Source = Sql.Database("sql-datamesh-datalake-prod-001-ondemand.sql.azuresynapse.net", "datalake"),\n    //udm_datamart_cust_exp_cust_exp_dim_calendar_v1 = Source{[Schema="udm_datamart_cust_exp",Item="cust_exp_dim_calendar_v1"]}[Data],\n    Source = Value.NativeQuery(Databricks.Catalogs("adb-6954534548722724.4.azuredatabricks.net", "/sql/1.0/warehouses/ba6033a2676da150", [Catalog="curated_cch_bw_mdm", Database=null, QueryTags=null, EnableAutomaticProxyDiscovery=null, Implementation="2.0", MetricViewBiCompatibilityMode=null]){[Name="curated_cch_bw_mdm",Kind="Database"]}[Data], "SELECT #(lf)TO_DATE(concat( LEFT(fiscper, 4),\'-\', RIGHT(fiscper, 2), \'-15\')) fiscper_date,#(lf)fiscper,#(lf)comp_code,#(lf)bic_csubkbi,#(lf)country,#(lf)bic_ccusthie4,#(lf)fltp#(lf) FROM `dc_datalake_prod_001`.`curated_cch_bw_mdm`.`ca_otc010_otc_subkbis`", null, [EnableFolding=true]),\n    CompanyCodesBuffer = List.Buffer(CompanyCodesMapping[#"Company Code"]),\n    FilterCompCodes = Table.SelectRows(Source, each List.Contains(CompanyCodesBuffer, [comp_code])),\n    ReplaceCountryIds = List.Accumulate(\n    {\n        {"GB", "NIR"}\n    },\n    FilterCompCodes,\n    (state, current) => Table.ReplaceValue(state, current{0}, current{1}, Replacer.ReplaceText, {"country"})),\n    // //For CaseFillRate, Order Accuracy and Orders delivered on time, we exclude data for other countries than Bulgaria until April 26\n    // FilterExclude3KBI = \n    //     Table.SelectRows(\n    //         ReplaceCountryIds,\n    //          each not(\n    //              (([bic_csubkbi] = "KIOM03501") or ([bic_csubkbi] = "KIOM03502") or ([bic_csubkbi] = "KIOM03503") or ([bic_csubkbi] = "KIOM03504") or ([bic_csubkbi] = "KIOM03505")) and \n    //              [country] <> "BG")),\n    #"Kept First Rows" = Table.FirstN(ReplaceCountryIds,RowLimit),\n \xa0\xa0 Result = if RowLimit > 0 then #"Kept First Rows" else ReplaceCountryIds\n    // #"Filtered Rows" = Table.SelectRows(Result, each ([fiscper] = "2026006"))\nin\n    Result'

FACT_CUSTOMEREXP_M = 'let\n\n   // Source = Sql.Database("sql-datamesh-datalake-prod-001-ondemand.sql.azuresynapse.net", "datalake"),\n   // udm_datamart_cust_exp_cust_exp_fact_data_v1 = Source{[Schema="udm_datamart_cust_exp",Item="cust_exp_fact_data_v2"]}[Data],\n     Source = Value.NativeQuery(Databricks.Catalogs("adb-6954534548722724.4.azuredatabricks.net", "/sql/1.0/warehouses/ba6033a2676da150", [Catalog="udm_datamart_cust_exp", Database=null, QueryTags=null, EnableAutomaticProxyDiscovery=null, Implementation="2.0", MetricViewBiCompatibilityMode=null]){[Name="udm_datamart_cust_exp",Kind="Database"]}[Data], "SELECT * FROM(#(lf)SELECT touchpoint,fiscper,country_id,distinct_customer_pulsed,#(lf)    TO_DATE(concat( LEFT(fiscper, 4),\'-\', RIGHT(fiscper, 2), \'-15\')) fiscper_date#(lf)    FROM#(lf)dc_datalake_prod_001.udm_datamart_cust_exp.cust_exp_fact_data#(lf)#(lf)WHERE lower(touchpoint) like \'relationship\')#(lf)WHERE fiscper_date >= MAKE_DATE(YEAR(CURRENT_DATE()) - 2, 1, 1)", null, [EnableFolding=true]),\n    Replace_GB_Val = Table.ReplaceValue(Source ,"GB","IE",Replacer.ReplaceText,{"country_id"}),\n\t#"Grouped Rows" = Table.Group(Replace_GB_Val, {"country_id", "fiscper_date"}, {{"CustomerPulsedTotal", each List.Sum([distinct_customer_pulsed]), type nullable number}}),\n    #"Kept First Rows" = Table.FirstN(#"Grouped Rows",RowLimit),\n \xa0\xa0 Result = if RowLimit > 0 then #"Kept First Rows" else #"Grouped Rows"\nin\n \xa0\xa0 Result'

DIM_COUNTRY_M = 'let\n   // Source = Sql.Database("sql-datamesh-datalake-prod-001-ondemand.sql.azuresynapse.net", "datalake"),\n    //udm_datamart_cust_exp_cust_exp_dim_company_v1 = Source{[Schema="udm_datamart_cust_exp",Item="cust_exp_dim_company_v1"]}[Data],\n    Source = Databricks.Catalogs(ServerHostName, HTTP_Path, null),\n    dc_datalake_prod_001_Database = Source{[Name="dc_datalake_prod_001",Kind="Database"]}[Data],\n    curated_cch_bw_md_Schema = dc_datalake_prod_001_Database{[Name="udm_datamart_cust_exp",Kind="Schema"]}[Data],\n    cust_exp_dim_company_v1 = curated_cch_bw_md_Schema{[Name="cust_exp_dim_company",Kind="View"]}[Data],\n    #"Removed Other Columns" = Table.SelectColumns(cust_exp_dim_company_v1,{"region_sequence_id", "region", "market_segment", "business_unit", "business_unit_abbreviation", "country", "country_abbreviation", "geo_country", "country_id"}),\n    #"FilterRegions&Finland" = Table.SelectRows(#"Removed Other Columns", each ([region] = "Italy" or [region] = "REGION 1" or [region] = "REGION 2" or [region] = "REGION 3" or ([country] = "Finlandia" and [region] = "New Business"))),\n    #"Removed Duplicates" = Table.Distinct(#"FilterRegions&Finland", {"country_abbreviation"}),\n    Exclude_RU_MU_BY_FV = Table.SelectRows(#"Removed Duplicates", each ([country_abbreviation] <> "RU") and ([country_abbreviation] <> "BY") and ([country_abbreviation] <> "MUL") and ([country_abbreviation] <> "FV")),\n    #"Replaced Value2" = Table.ReplaceValue(Exclude_RU_MU_BY_FV,"Baltics","Estonia",Replacer.ReplaceText,{"country"}),\n    #"Replaced Value1" = Table.ReplaceValue(#"Replaced Value2","Republic of Ireland","Ireland",Replacer.ReplaceText,{"country"}),\n\n    //Some countries have different country_id between this table and OTC table\n    ReplaceCountryIds = List.Accumulate(\n        {\n            {"ROI","IE"},\n            {"CR",  "HR"},\n            {"NMD", "MK"},\n            {"XK",  "KV"},\n            {"FV","FI"}\n        },\n        #"Replaced Value1",\n        (state, current) => Table.ReplaceValue(state, current{0}, current{1}, Replacer.ReplaceText, {"country_id"})\n    ),\n\n    AddLatviaLithuaniaRecords = Table.Combine({\n        ReplaceCountryIds,\n        Table.FromRecords({\n            [region_sequence_id = 2, region = "REGION 1", market_segment = "Developing", business_unit = "BU Poland & Baltics", business_unit_abbreviation = "PL & BAL", country = "Lithuania", country_abbreviation = "LT", geo_country = "Lithuania", country_id = "LT"],\n            [region_sequence_id = 2, region = "REGION 1", market_segment = "Developing", business_unit = "BU Poland & Baltics", business_unit_abbreviation = "PL & BAL", country = "Latvia", country_abbreviation = "LV", geo_country = "Latvia", country_id = "LV"],\n            [region_sequence_id = 2, region = "REGION 1", market_segment = "Developing", business_unit = "Ireland", business_unit_abbreviation = "IOI", country = "United Kingdom", country_abbreviation = "GB", geo_country = "United Kingdom", country_id = "GB"]\n        })\n    }),\n\n    // Added 2 new rows from your extracted query\n    AddBSOAndCSCRows = Table.Combine({\n        AddLatviaLithuaniaRecords,\n        Table.FromRecords({\n            [region_sequence_id = 8, region = "BSO", market_segment = "Developing", business_unit = "BSO", business_unit_abbreviation = "BSO", country = "BSO_EMP", country_abbreviation = "BSO_EMP", geo_country = "BSO_EMP", country_id = "BSO_EMP"],\n            [region_sequence_id = 9, region = "CSC", market_segment = "Developing", business_unit = "CSC", business_unit_abbreviation = "CSC", country = "CSC", country_abbreviation = "CSC", geo_country = "CSC", country_id = "CSC"]\n        })\n    }),\n\n    #"Kept First Rows" = Table.FirstN(AddBSOAndCSCRows, RowLimit),\n    Result = if RowLimit > 0 then #"Kept First Rows" else AddBSOAndCSCRows,\n    #"Changed Type" = Table.TransformColumnTypes(Result,{{"country", type text}, {"business_unit_abbreviation", type text}, {"business_unit", type text}, {"market_segment", type text}, {"region", type text}, {"region_sequence_id", Int64.Type}, {"country_abbreviation", type text}})\nin\n    #"Changed Type"'
